// Screenshot previews at true mobile/desktop viewports via Chrome DevTools Protocol.
// Headless --window-size can't go below ~500px wide on Windows, so we emulate instead.
import { spawn } from "node:child_process";
import { writeFileSync, readdirSync, statSync, existsSync, mkdirSync } from "node:fs";
import { join, resolve } from "node:path";

const ROOT = resolve(".");
const SOLD = join(ROOT, "private", "outreach", "_sold");
const OUT = join(ROOT, "private", "outreach", "shots");
const CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe";
const PORT = 9377;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const chrome = spawn(CHROME, [
  "--headless", "--disable-gpu", "--hide-scrollbars", "--no-first-run",
  `--remote-debugging-port=${PORT}`, "--user-data-dir=/tmp/cdp-shots", "about:blank",
], { stdio: "ignore" });

async function targets() {
  for (let i = 0; i < 40; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      if (r.ok) return (await r.json()).filter(t => t.type === "page");
    } catch {}
    await sleep(300);
  }
  throw new Error("Chrome DevTools endpoint never came up");
}

const pages = await targets();
const ws = new WebSocket(pages[0].webSocketDebuggerUrl);
let seq = 0;
const pending = new Map();
const waiters = [];
ws.onmessage = e => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  else if (m.method) for (const w of [...waiters]) if (w.method === m.method) { w.res(m); waiters.splice(waiters.indexOf(w), 1); }
};
const send = (method, params = {}) => new Promise(res => { const i = ++seq; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const waitEvent = method => new Promise(res => waiters.push({ method, res }));
await new Promise(r => { ws.onopen = r; });
await send("Page.enable");

const slugs = readdirSync(SOLD).filter(d => statSync(join(SOLD, d)).isDirectory() && existsSync(join(SOLD, d, "index.html")));
mkdirSync(OUT, { recursive: true });
const fileBase = "file:///" + SOLD.replace(/\\/g, "/");

let done = 0;
for (const slug of slugs) {
  for (const [tag, w, h, dsf, mobile] of [["mobile", 375, 1000, 1, true], ["desktop", 1280, 800, 1, false]]) {
    await send("Emulation.setDeviceMetricsOverride", { width: w, height: h, deviceScaleFactor: dsf, mobile });
    const loaded = waitEvent("Page.loadEventFired");
    await send("Page.navigate", { url: `${fileBase}/${slug}/index.html` });
    await Promise.race([loaded, sleep(4000)]);
    await sleep(350);
    const shot = await send("Page.captureScreenshot", { format: "png" });
    writeFileSync(join(OUT, `${slug}-${tag}.png`), Buffer.from(shot.result.data, "base64"));
  }
  done++;
}
console.log(`${done} slugs x2 -> ${OUT}`);
ws.close();
chrome.kill();
process.exit(0);

